// ================== CONEXIÓN REAL A SUPABASE ==================
// Reemplaza el guardado de simulación (window.storage) por la base de datos
// real de Estación Fit, donde ya viven los 110 clientes existentes.
//
// Se usa fetch() directo a la API REST de Supabase (PostgREST) en vez del
// paquete @supabase/supabase-js, a propósito: así el mismo código funciona
// tanto en la vista previa de Claude como una vez publicado en Vercel — no
// depende de instalar ningún paquete adicional.
const SUPABASE_URL = "https://epscbdnsdcdybhlpgrij.supabase.co";
const SUPABASE_KEY = "sb_publishable_RKvLiPxlHwMmzl9cx2qXEQ_i9Ru7r8d";
const SUPABASE_TABLE = "clientes";

// IMPORTANTE: las llaves nuevas de Supabase (sb_publishable_..., sb_secret_...)
// NO se envían en el header "Authorization: Bearer" — Supabase las rechaza ahí
// porque no son JWT. Solo van en el header "apikey". Este fue el bug que hacía
// que la app no encontrara a los clientes reales y usara los de ejemplo.
const supaHeaders = {
  apikey: SUPABASE_KEY,
  "Content-Type": "application/json",
};

// Trae los 110+ clientes reales desde Supabase.
async function supaFetchAll() {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${SUPABASE_TABLE}?select=*&order=creado_en.desc`, {
    headers: supaHeaders,
  });
  if (!res.ok) throw new Error("No se pudo leer la base de datos");
  return res.json();
}

// Crea un cliente nuevo (Supabase genera el id real automáticamente).
async function supaInsert(row) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${SUPABASE_TABLE}`, {
    method: "POST",
    headers: { ...supaHeaders, Prefer: "return=representation" },
    body: JSON.stringify(row),
  });
  if (!res.ok) throw new Error("No se pudo crear el cliente");
  const data = await res.json();
  return data[0];
}

// Actualiza un cliente existente por su id real de Supabase.
async function supaUpdate(id, patch) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${SUPABASE_TABLE}?id=eq.${id}`, {
    method: "PATCH",
    headers: { ...supaHeaders, Prefer: "return=representation" },
    body: JSON.stringify(patch),
  });
  if (!res.ok) throw new Error("No se pudo actualizar el cliente");
  const data = await res.json();
  return data[0];
}

// ---- Traductores entre las columnas de Supabase (español, snake_case) y el
// modelo que ya usa toda la app (name, phone, cardsCompleted, history, etc.) ----
// Así NO hay que reescribir ninguna de las pantallas/lógica ya construidas y
// probadas — solo se traduce al entrar y salir de la base de datos.
function rowToCustomer(row) {
  return {
    id: row.id,
    slug: row.slug,
    name: row.nombre,
    phone: row.telefono || "",
    filled: row.filled ?? 0,
    cardsCompleted: row.completadas ?? 0,
    history: row.historial || [],
    glamfitBenefit: row.glamfit_benefit || null,
    beautyHouseBenefit: row.beauty_house_benefit || null,
    capMissions: row.cap_missions || { social: false, visitTag: false, review: false },
    capClaimedAt: row.cap_claimed_en || null,
  };
}

function customerToRow(customer) {
  return {
    slug: customer.slug,
    nombre: customer.name,
    telefono: customer.phone,
    filled: customer.filled,
    completadas: customer.cardsCompleted,
    historial: customer.history,
    glamfit_benefit: customer.glamfitBenefit,
    beauty_house_benefit: customer.beautyHouseBenefit,
    cap_missions: customer.capMissions,
    cap_claimed_en: customer.capClaimedAt,
  };
}

// Genera un slug único (ej. "carlas-honda") a partir del nombre, evitando
// choques con clientes que ya existan.
function slugify(name) {
  return name
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // quita tildes
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
function generateUniqueSlug(name, existingCustomers) {
  const base = slugify(name) || "cliente";
  const taken = new Set((existingCustomers || []).map((c) => c.slug));
  if (!taken.has(base)) return base;
  let i = 2;
  while (taken.has(`${base}-${i}`)) i++;
  return `${base}-${i}`;
}
