// ---------- Lógica del programa de fidelidad ----------
// 9 círculos por tarjeta.
// Círculo 3 -> 10% descuento
// Círculo 6 -> 15% descuento
// Círculo 9 -> consumo gratis, luego reinicia
function getCircleReward(circleNumber) {
  if (circleNumber === 3) return { label: "10%", type: "percent" };
  if (circleNumber === 6) return { label: "15%", type: "percent" };
  if (circleNumber === 9) return { label: "GRATIS", type: "free" };
  return null;
}

// Mensaje dinámico según el progreso actual (0-9). Pura presentación:
// no toca la lógica de sellos/recompensas existente.
function getProgressMessage(filled) {
  if (filled >= 9) return "🎉 ¡Tarjeta completada!";
  if (filled === 8) return "👀 ¡Te falta solo 1 consumo!";
  if (filled >= 6) return "🚀 ¡Ya estás cerca! No pares ahora.";
  if (filled >= 3) return "🔥 ¡Vas muy bien! Sigue acumulando sellos.";
  return "🌱 ¡Empezaste! Cada compra te acerca a tu recompensa.";
}

function makeCustomer(name, phone) {
  const id = Math.random().toString(36).slice(2, 8).toUpperCase();
  return {
    id,
    name,
    phone,
    filled: 0,
    cardsCompleted: 0,
    history: [],
    // glamfitBenefit: null mientras no se ha desbloqueado ningún beneficio.
    // Al completar el sello 9 (stampVisit) se llena con:
    //   { unlockedAt, code, redeemedAt }
    // - unlockedAt: momento real del desbloqueo (Fase 5), base de la vigencia (Fase 6).
    // - code: código único "FIT-XXXX" generado UNA sola vez (Fase 7).
    // - redeemedAt: null hasta que se marca como canjeado (Fase 7); una vez usado,
    //   el beneficio queda CANJEADO para siempre, sin importar si seguía vigente.
    glamfitBenefit: null,
    // beautyHouseBenefit: null hasta el sello 9 (mismo trigger que Glamfit). Estructura
    // paralela + un campo extra "choice" ("asesoria" | "descuento" | null) porque acá el
    // cliente elige UNO de dos beneficios antes de que exista el cupón/pantalla final.
    beautyHouseBenefit: null,
    // Fase E: Reto Gorra — completamente INDEPENDIENTE del sistema de sellos.
    // No se desbloquea al completar la tarjeta; son 3 misiones que solo el
    // mostrador puede marcar (confirmado con el cliente), porque la app no puede
    // verificar por sí sola si alguien siguió una cuenta, etiquetó una foto o dejó
    // una reseña. capClaimedAt queda null hasta que se le entrega la gorra física.
    capMissions: { social: false, visitTag: false, review: false },
    capClaimedAt: null,
  };
}

