// ---------- Anillo de progreso circular (Reto Gorra) ----------
function CircularProgressRing({ completed, total, size = 64 }) {
  const strokeWidth = 6;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const pct = total > 0 ? completed / total : 0;
  const dash = circumference * pct;
  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <svg width={size} height={size} style={{ transform: "rotate(-90deg)" }}>
        <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke={BRAND.mid} strokeWidth={strokeWidth} />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={BRAND.base}
          strokeWidth={strokeWidth}
          strokeDasharray={`${dash} ${circumference - dash}`}
          strokeLinecap="round"
        />
      </svg>
      <div className="absolute inset-0 flex items-center justify-center">
        <p className="font-display font-extrabold leading-none" style={{ color: BRAND.dark, fontSize: size * 0.32 }}>
          {completed}
          <span style={{ fontSize: size * 0.18, fontWeight: 600, color: "rgba(35,41,29,0.4)" }}>/{total}</span>
        </p>
      </div>
    </div>
  );
}

