// ---------- Beneficio de alianza: GLAMFIT ----------
// Beneficio especial de alianza, NO es un sello adicional. Los 9 sellos existentes
// no cambian. Este beneficio se desbloquea al completar la tarjeta (sello 9).
const GLAMFIT_DISCOUNT_LABEL = "20% OFF";
const GLAMFIT_VALID_DAYS = 15;

// Fase 6: vigencia calculada SIEMPRE en vivo a partir de glamfitBenefit.unlockedAt.
// Nunca se guarda una fecha de vencimiento fija: expiresAt sale de sumarle 15 días
// al momento real de desbloqueo, cada vez que se llama a esta función.
function getGlamfitValidity(benefit) {
  if (!benefit?.unlockedAt) return null;
  const unlockedAt = new Date(benefit.unlockedAt);
  const expiresAt = new Date(unlockedAt.getTime() + GLAMFIT_VALID_DAYS * 24 * 60 * 60 * 1000);
  const msLeft = expiresAt.getTime() - Date.now();
  return {
    unlockedAt,
    expiresAt,
    isExpired: msLeft <= 0,
    daysLeft: Math.max(0, Math.ceil(msLeft / (24 * 60 * 60 * 1000))),
  };
}

// Fase 7: código único de beneficio. Se genera UNA sola vez, en el momento del
// desbloqueo (ver stampVisit), y se guarda en glamfitBenefit.code — nunca se
// recalcula en cada render. Se evitan caracteres ambiguos (0/O, 1/I).
function generateBenefitCode() {
  const chars = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
  let suffix = "";
  for (let i = 0; i < 4; i++) suffix += chars[Math.floor(Math.random() * chars.length)];
  return `FIT-${suffix}`;
}

// Fase 7: estado formal del beneficio, combinando vigencia (Fase 6) + canje.
// Devuelve uno de: "locked" | "active" (= DESBLOQUEADO/VIGENTE) | "redeemed" (= CANJEADO) | "expired" (= VENCIDO).
// Un beneficio canjeado NUNCA vuelve a estar activo, incluso si técnicamente seguía vigente.
function getGlamfitStatus(benefit) {
  if (!benefit) return { state: "locked" };
  if (benefit.redeemedAt) return { state: "redeemed", redeemedAt: new Date(benefit.redeemedAt) };
  const validity = getGlamfitValidity(benefit);
  if (!validity) return { state: "locked" };
  return { state: validity.isExpired ? "expired" : "active", ...validity };
}

// Fase 7: estructura simple y preparada para que Glamfit valide un código en el
// futuro (terminal en tienda, endpoint, etc). A propósito NO se construye un panel
// administrativo completo todavía — solo la función pura que respondería:
// ¿existe el código?, ¿a qué cliente pertenece?, ¿está vigente?, ¿ya fue usado?
function validateGlamfitCode(customers, rawCode) {
  const code = (rawCode || "").trim().toUpperCase();
  const owner = (customers || []).find((c) => c.glamfitBenefit?.code === code);
  if (!owner) return { valid: false, reason: "not_found" };

  const status = getGlamfitStatus(owner.glamfitBenefit);
  if (status.state === "redeemed") return { valid: false, reason: "already_redeemed", customerName: owner.name };
  if (status.state === "expired") return { valid: false, reason: "expired", customerName: owner.name };
  if (status.state !== "active") return { valid: false, reason: "not_unlocked" };
  return { valid: true, customerName: owner.name, customerId: owner.id, code };
}

// ---------- Beneficio de alianza: BEAUTY HOUSE (Fase C) ----------
// Segundo aliado, independiente de Glamfit. Se desbloquea en el MISMO momento
// (sello 9), pero el cliente elige UNO de dos beneficios: asesoría de imagen
// gratis, o 10% OFF en servicios. La estructura es deliberadamente paralela a la
// de Glamfit (mismos nombres de campo) para que sea fácil de mantener, pero se
// mantiene como funciones separadas para no arriesgar romper nada de Glamfit.
const BEAUTYHOUSE_VALID_DAYS = 15;
const BEAUTYHOUSE_ADVICE_VALUE = "S/50";
const BEAUTYHOUSE_DISCOUNT_LABEL = "10% OFF";

function getBeautyHouseValidity(benefit) {
  if (!benefit?.unlockedAt) return null;
  const unlockedAt = new Date(benefit.unlockedAt);
  const expiresAt = new Date(unlockedAt.getTime() + BEAUTYHOUSE_VALID_DAYS * 24 * 60 * 60 * 1000);
  const msLeft = expiresAt.getTime() - Date.now();
  return {
    unlockedAt,
    expiresAt,
    isExpired: msLeft <= 0,
    daysLeft: Math.max(0, Math.ceil(msLeft / (24 * 60 * 60 * 1000))),
  };
}

function generateBeautyHouseCode() {
  const chars = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
  let suffix = "";
  for (let i = 0; i < 4; i++) suffix += chars[Math.floor(Math.random() * chars.length)];
  return `BH-${suffix}`;
}

// Estado: "locked" | "active" (desbloqueado, con o sin elección todavía) | "redeemed" | "expired".
// El campo benefit.choice ("asesoria" | "descuento" | null) se lee aparte de este estado,
// para decidir qué pantalla mostrar cuando el beneficio está "active".
function getBeautyHouseStatus(benefit) {
  if (!benefit) return { state: "locked" };
  if (benefit.redeemedAt) return { state: "redeemed", redeemedAt: new Date(benefit.redeemedAt) };
  const validity = getBeautyHouseValidity(benefit);
  if (!validity) return { state: "locked" };
  return { state: validity.isExpired ? "expired" : "active", ...validity };
}

// Misma idea que validateGlamfitCode: estructura simple y preparada para que Beauty
// House (Angelo o su equipo) valide un código en el futuro. Solo aplica al camino
// de "10% OFF", ya que la asesoría gratis no usa código (ver spec de la pantalla 3).
function validateBeautyHouseCode(customers, rawCode) {
  const code = (rawCode || "").trim().toUpperCase();
  const owner = (customers || []).find((c) => c.beautyHouseBenefit?.code === code);
  if (!owner) return { valid: false, reason: "not_found" };

  const status = getBeautyHouseStatus(owner.beautyHouseBenefit);
  if (status.state === "redeemed") return { valid: false, reason: "already_redeemed", customerName: owner.name };
  if (status.state === "expired") return { valid: false, reason: "expired", customerName: owner.name };
  if (status.state !== "active") return { valid: false, reason: "not_unlocked" };
  return { valid: true, customerName: owner.name, customerId: owner.id, code };
}

// ---------- Reto Gorra (Fase E) ----------
// Independiente del sistema de sellos y de los aliados (Glamfit/Beauty House).
// Las 3 misiones las marca el mostrador — la app no puede verificar por sí sola
// si alguien siguió una cuenta, subió una foto o dejó una reseña.
const CAP_MISSIONS = [
  { key: "social", icon: Heart, title: "Síguenos en redes", desc: "Síguenos en Instagram y TikTok @estacionfit.lima" },
  { key: "visitTag", icon: Camera, title: "Etiquétanos en tu visita", desc: "Ven a Estación Fit, toma una foto o video y etiquétanos en Instagram @estacionfit.lima" },
  { key: "review", icon: Star, title: "Déjanos una reseña", desc: "Déjanos una reseña en el perfil de Estación FIT en Google Maps" },
];

// Estado derivado (nunca se guarda aparte): cuenta misiones hechas, si ya se
// completaron las 3, y si la gorra física ya fue entregada.
function getCapMissionsStatus(customer) {
  const missions = customer?.capMissions || { social: false, visitTag: false, review: false };
  const completedCount = CAP_MISSIONS.filter((m) => missions[m.key]).length;
  return {
    missions,
    completedCount,
    total: CAP_MISSIONS.length,
    allDone: completedCount === CAP_MISSIONS.length,
    claimed: !!customer?.capClaimedAt,
  };
}

