// ---------- Experiencia de celebración al completar la tarjeta (sello 9) ----------
// Se dispara solo en el momento en que se marca el consumo que completa la tarjeta.
// Confeti liviano en CSS (respeta prefers-reduced-motion) + resumen de las DOS
// recompensas que se obtienen: el producto gratis (sello 9, ya existente) y el
// beneficio nuevo de alianza (20% OFF Glamfit, desbloqueado en esta misma fase).
const CONFETTI_COLORS = [BRAND.gold, BRAND.rust, BRAND.base, BRAND.accent];

function Confetti() {
  const pieces = Array.from({ length: 24 });
  return (
    <div className="absolute inset-0 overflow-hidden pointer-events-none" aria-hidden="true">
      {pieces.map((_, i) => {
        const left = Math.round((i / pieces.length) * 100 + (i % 3) * 2);
        const delay = (i % 8) * 0.12;
        const duration = 1.8 + (i % 5) * 0.3;
        const color = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
        const size = 6 + (i % 3) * 2;
        return (
          <span
            key={i}
            className="confetti-piece absolute top-0 rounded-sm"
            style={{
              left: `${left}%`,
              width: size,
              height: size * 0.5,
              background: color,
              animationDuration: `${duration}s`,
              animationDelay: `${delay}s`,
            }}
          />
        );
      })}
    </div>
  );
}

