// ---------- Vista: detalle de cliente (mostrador) ----------
function DetailView({ customer, onBack, onStamp, onUndo, celebrating, onDismissCelebration, onToggleCapMission, onClaimCapReward }) {
  const [justStamped, setJustStamped] = useState(false);
  const [copied, setCopied] = useState(false);
  const nextReward = getCircleReward(customer.filled + 1);
  // Usa el dominio real una vez publicado en Vercel; localmente cae a location.origin.
  const shareLink = `${typeof window !== "undefined" ? window.location.origin : "https://tarjeta.estacionfit.pe"}/${customer.slug}`;

  function copyLink() {
    navigator.clipboard?.writeText(shareLink).catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  }

  // Arma el mensaje de bienvenida + link, y abre WhatsApp con todo ya escrito
  // (el cliente solo tiene que darle "Enviar"). Normaliza el teléfono guardado
  // (ej. "0991 234 567") al formato internacional que espera WhatsApp (51991234567).
  function shareOnWhatsApp() {
    const firstName = customer.name.split(" ")[0];
    const message =
      `¡Hola, ${firstName}! 👋 Bienvenid@ a la familia Estación FIT 💪\n\n` +
      `Esta es tu tarjeta digital: acumula sellos con cada visita y desbloquea descuentos, regalos y beneficios exclusivos 🎁✨\n\n` +
      `Guárdala en tu pantalla de inicio para tenerla siempre a la mano:\n${shareLink}`;

    let digits = (customer.phone || "").replace(/\D/g, "");
    if (digits.startsWith("0")) digits = digits.slice(1); // quita el 0 inicial local
    if (!digits.startsWith("51")) digits = `51${digits}`; // agrega código de Perú si falta

    window.open(`https://wa.me/${digits}?text=${encodeURIComponent(message)}`, "_blank");
  }

  function handleStamp() {
    onStamp();
    setJustStamped(true);
    setTimeout(() => setJustStamped(false), 550);
  }

  return (
    <div className="flex-1 flex flex-col px-6 pt-8 pb-10">
      <button onClick={onBack} className="flex items-center gap-1.5 text-sm mb-6" style={{ color: "rgba(35,41,29,0.6)" }}>
        <ArrowLeft className="w-4 h-4" /> Volver
      </button>

      <div className="mb-5">
        <h1 className="font-display text-2xl font-extrabold" style={{ color: BRAND.dark }}>{customer.name}</h1>
        <p className="text-sm" style={{ color: "rgba(35,41,29,0.55)" }}>{customer.phone}</p>
        {customer.cardsCompleted > 0 && (
          <p className="text-xs font-semibold mt-1.5 flex items-center gap-1" style={{ color: BRAND.accentDark }}>
            <Gift className="w-3.5 h-3.5" /> {customer.cardsCompleted} {customer.cardsCompleted === 1 ? "tarjeta completada" : "tarjetas completadas"}
          </p>
        )}
      </div>

      <button
        onClick={copyLink}
        className="mb-3 rounded-2xl px-4 py-3 flex items-center gap-2.5 text-left transition-colors"
        style={{ background: "rgba(35,41,29,0.06)" }}
      >
        <Share2 className="w-4 h-4 shrink-0" style={{ color: "rgba(35,41,29,0.45)" }} />
        <span className="text-[11px] leading-snug flex-1" style={{ color: "rgba(35,41,29,0.7)" }}>
          Link personal para que vea su tarjeta: <span className="font-mono" style={{ color: BRAND.ink }}>{shareLink}</span>
        </span>
        <span className="text-[10px] font-bold shrink-0" style={{ color: BRAND.accentDark }}>{copied ? "¡Copiado!" : "Copiar"}</span>
      </button>

      <button
        onClick={shareOnWhatsApp}
        className="mb-5 rounded-2xl px-4 py-3 flex items-center justify-center gap-2 text-sm font-semibold text-white active:scale-[0.98] transition-transform"
        style={{ background: "#25D366" }}
      >
        <MessageCircle className="w-4 h-4" /> Enviar tarjeta por WhatsApp
      </button>

      <LoyaltyCard filled={customer.filled} justStamped={justStamped} />
      <RewardBanner nextReward={nextReward} perspective="owner" />

      <div className="flex-1" />

      <button
        onClick={handleStamp}
        className="w-full rounded-2xl py-5 font-bold flex items-center justify-center gap-2 shadow-lg active:scale-[0.98] transition-transform text-base text-white"
        style={{ background: BRAND.accent }}
      >
        <EFStamp size="w-6 h-6" />
        Marcar consumo de hoy
      </button>

      {customer.filled > 0 && (
        <button onClick={onUndo} className="w-full mt-2 py-2.5 text-xs flex items-center justify-center gap-1.5" style={{ color: "rgba(35,41,29,0.45)" }}>
          <RotateCcw className="w-3.5 h-3.5" />
          Deshacer última marca
        </button>
      )}

      {customer.history.length > 0 && (
        <div className="mt-6">
          <p className="text-xs font-semibold uppercase tracking-wide mb-2" style={{ color: "rgba(35,41,29,0.45)" }}>Historial reciente</p>
          <div className="space-y-1.5">
            {customer.history.slice(0, 4).map((h, i) => (
              <div key={i} className="flex justify-between text-xs py-1 border-b" style={{ color: "rgba(35,41,29,0.6)", borderColor: "rgba(218,214,196,0.5)" }}>
                <span>Círculo {h.circle} · {h.date}</span>
                {h.reward && <span className="font-bold" style={{ color: BRAND.accentDark }}>{h.reward}</span>}
              </div>
            ))}
          </div>
        </div>
      )}

      <CapMissionsStaffPanel customer={customer} onToggleMission={onToggleCapMission} onClaim={onClaimCapReward} />

      {celebrating && <CardCompletedCelebration customer={customer} onDismiss={onDismissCelebration} />}
    </div>
  );
}

// ---------- Reto Gorra: panel del mostrador (Fase E) ----------
// El staff marca cada misión con un toggle (puede desmarcar si se equivocó) y
// entrega la gorra física cuando las 3 estén listas. El cliente NO ve este panel.
function CapMissionsStaffPanel({ customer, onToggleMission, onClaim }) {
  const capStatus = getCapMissionsStatus(customer);

  return (
    <div className="mt-6 rounded-2xl border p-4" style={{ borderColor: BRAND.mid, background: BRAND.paleAlt }}>
      <div className="flex items-center justify-between mb-3">
        <p className="text-xs font-bold uppercase tracking-wide flex items-center gap-1.5" style={{ color: BRAND.dark }}>
          🧢 Reto Gorra
        </p>
        <span className="text-[10px] font-bold px-2 py-0.5 rounded-full" style={{ background: `${BRAND.goldDark}18`, color: BRAND.goldDark }}>
          {capStatus.completedCount}/{capStatus.total}
        </span>
      </div>

      {capStatus.claimed ? (
        <p className="text-xs flex items-center gap-1.5" style={{ color: "rgba(35,41,29,0.55)" }}>
          <Check className="w-3.5 h-3.5" style={{ color: BRAND.base }} /> Gorra ya entregada.
        </p>
      ) : (
        <>
          <div className="space-y-2 mb-3">
            {CAP_MISSIONS.map((m) => {
              const done = capStatus.missions[m.key];
              return (
                <button
                  key={m.key}
                  onClick={() => onToggleMission(customer.id, m.key)}
                  className="w-full flex items-center gap-2.5 text-left"
                >
                  <div
                    className="w-5 h-5 rounded-md flex items-center justify-center shrink-0 border"
                    style={{ background: done ? BRAND.base : "transparent", borderColor: done ? BRAND.base : BRAND.mid }}
                  >
                    {done && <Check className="w-3.5 h-3.5 text-white" />}
                  </div>
                  <span className="text-xs" style={{ color: done ? BRAND.dark : "rgba(35,41,29,0.65)" }}>{m.title}</span>
                </button>
              );
            })}
          </div>
          <button
            onClick={() => onClaim(customer.id)}
            disabled={!capStatus.allDone}
            className="w-full rounded-xl py-2.5 text-xs font-semibold text-white"
            style={{ background: capStatus.allDone ? BRAND.goldDark : "rgba(35,41,29,0.15)" }}
          >
            {capStatus.allDone ? "Marcar gorra entregada" : "Faltan misiones por completar"}
          </button>
        </>
      )}
    </div>
  );
}

// ---------- Vista: lo que ve el CLIENTE en su propio teléfono ----------
function ClientView({ customers, customer, onSelect, allowSwitching = true, onRedeemBenefit, onChooseBeautyHouse, onChangeBeautyHouseChoice, onRedeemBeautyHouse }) {
  const [showGlamfit, setShowGlamfit] = useState(false);
  const [showBenefitScreen, setShowBenefitScreen] = useState(false);
  const [showBeautyHouse, setShowBeautyHouse] = useState(false);
  const [showBeautyHouseModal, setShowBeautyHouseModal] = useState(false);
  const [showEstacionShop, setShowEstacionShop] = useState(false);
  const [showCapMissions, setShowCapMissions] = useState(false);

  if (!customer) {
    return (
      <div className="flex-1 flex items-center justify-center text-sm px-6 text-center" style={{ color: "rgba(35,41,29,0.5)" }}>
        No hay clientes registrados todavía.
      </div>
    );
  }

  if (showBenefitScreen) {
    return (
      <GlamfitBenefitView
        customer={customer}
        onBack={() => setShowBenefitScreen(false)}
        onRedeem={() => onRedeemBenefit(customer.id)}
      />
    );
  }

  if (showBeautyHouse) {
    return (
      <BeautyHouseView
        customer={customer}
        onBack={() => setShowBeautyHouse(false)}
        onChoose={(choice) => onChooseBeautyHouse(customer.id, choice)}
        onChangeChoice={() => onChangeBeautyHouseChoice(customer.id)}
        onRedeem={() => onRedeemBeautyHouse(customer.id)}
      />
    );
  }

  if (showEstacionShop) {
    return ESTACION_SHOP_ENABLED ? (
      <EstacionShopView onBack={() => setShowEstacionShop(false)} />
    ) : (
      <EstacionShopComingSoonView onBack={() => setShowEstacionShop(false)} />
    );
  }

  if (showCapMissions) {
    return <CapMissionsView customer={customer} onBack={() => setShowCapMissions(false)} />;
  }

  const nextReward = getCircleReward(customer.filled + 1);
  const shareLink = `${typeof window !== "undefined" ? window.location.origin : "https://tarjeta.estacionfit.pe"}/${customer.slug}`;
  const firstName = customer.name.split(" ")[0];
  const initial = firstName.charAt(0).toUpperCase();

  // Fase 7: estado formal del beneficio Glamfit (locked / active / redeemed / expired),
  // derivado siempre en vivo — nunca se guarda un estado fijo aparte de redeemedAt.
  const glamfitStatusInfo = getGlamfitStatus(customer.glamfitBenefit);
  const glamfitStatus = glamfitStatusInfo.state;
  // Fase C: mismo patrón para Beauty House.
  const beautyHouseStatusInfo = getBeautyHouseStatus(customer.beautyHouseBenefit);
  const beautyHouseStatus = beautyHouseStatusInfo.state;
  // Fase E: progreso real de misiones para la mini-tarjeta del Club.
  const capStatus = getCapMissionsStatus(customer);
  const pct = Math.round((customer.filled / 9) * 100);
  const remaining = 9 - customer.filled;

  return (
    <div className="flex-1 flex flex-col px-6 pt-3 pb-10" style={{ background: BRAND.pale }}>
      {allowSwitching && (
        <div className="mb-5">
          <p className="text-[10px] uppercase tracking-wide mb-1.5 font-semibold" style={{ color: "rgba(35,41,29,0.4)" }}>
            Simulando que este cliente abre su link
          </p>
          <select
            value={customer.id}
            onChange={(e) => onSelect(e.target.value)}
            className="w-full bg-white border rounded-xl px-3 py-2 text-xs outline-none"
            style={{ borderColor: BRAND.mid }}
          >
            {customers.map((c) => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
        </div>
      )}

      {/* Encabezado: marca + saludo personalizado */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div
            className="w-11 h-11 rounded-full flex items-center justify-center font-display font-bold text-sm text-white shrink-0"
            style={{ background: BRAND.base }}
          >
            {initial}
          </div>
          <div>
            <p className="text-[10px] tracking-[0.16em] uppercase font-bold mb-0.5" style={{ color: BRAND.accentDark }}>
              Estación Fit · Tarjeta Fit
            </p>
            <h1 className="font-display text-lg font-extrabold leading-tight" style={{ color: BRAND.dark }}>
              ¡Hola, {firstName}! 👋
            </h1>
            <p className="text-[11px]" style={{ color: "rgba(35,41,29,0.5)" }}>
              Gracias por ser parte de nuestra comunidad FIT.
            </p>
          </div>
        </div>
        <div
          className="w-9 h-9 rounded-full flex items-center justify-center shrink-0"
          style={{ background: "white", border: `1px solid ${BRAND.mid}` }}
        >
          <Bell className="w-4 h-4" style={{ color: BRAND.dark }} />
        </div>
      </div>

      {/* Progreso dinámico */}
      <div className="rounded-3xl p-6 mb-5 text-center" style={{ background: BRAND.base }}>
        <p className="text-[10px] uppercase tracking-[0.18em] font-bold flex items-center justify-center gap-1.5 mb-2 text-white">
          <Flame className="w-3.5 h-3.5" /> Tu progreso
        </p>
        <p className="font-display text-4xl font-extrabold text-white mb-3">
          {customer.filled} <span className="text-xl font-semibold" style={{ color: "rgba(255,255,255,0.6)" }}>/ 9</span>
        </p>
        <div className="h-2 rounded-full overflow-hidden mb-3" style={{ background: "rgba(255,255,255,0.22)" }}>
          <div className="h-full rounded-full transition-all" style={{ width: `${pct}%`, background: BRAND.pale }} />
        </div>
        <p className="text-xs font-medium mb-1" style={{ color: "rgba(255,255,255,0.85)" }}>
          {remaining > 0
            ? `Te faltan ${remaining} ${remaining === 1 ? "consumo" : "consumos"} para desbloquear tus recompensas.`
            : "Completaste tu tarjeta FIT."}
        </p>
        <p className="text-xs font-semibold text-white">
          {getProgressMessage(customer.filled)}
        </p>
      </div>

      <LoyaltyCard filled={customer.filled} justStamped={false} />
      <RewardBanner nextReward={nextReward} perspective="client" />
      <ClubSection
        glamfitStatus={glamfitStatus}
        glamfitDaysLeft={glamfitStatusInfo.daysLeft ?? null}
        onOpenGlamfit={() => (glamfitStatus === "active" ? setShowBenefitScreen(true) : setShowGlamfit(true))}
        beautyHouseStatus={beautyHouseStatus}
        beautyHouseDaysLeft={beautyHouseStatusInfo.daysLeft ?? null}
        onOpenBeautyHouse={() => (beautyHouseStatus === "active" ? setShowBeautyHouse(true) : setShowBeautyHouseModal(true))}
        onOpenShop={() => setShowEstacionShop(true)}
        capCompleted={capStatus.completedCount}
        capTotal={capStatus.total}
        capClaimed={capStatus.claimed}
        onOpenCap={() => setShowCapMissions(true)}
      />

      {customer.cardsCompleted > 0 && (
        <p className="text-center text-xs font-semibold mb-5 flex items-center justify-center gap-1" style={{ color: BRAND.accentDark }}>
          <Gift className="w-3.5 h-3.5" /> Ya completaste {customer.cardsCompleted} {customer.cardsCompleted === 1 ? "tarjeta" : "tarjetas"}
        </p>
      )}

      <div className="mt-auto rounded-2xl px-4 py-3 flex items-center gap-2.5" style={{ background: "rgba(35,41,29,0.06)" }}>
        <Share2 className="w-4 h-4 shrink-0" style={{ color: "rgba(35,41,29,0.4)" }} />
        <p className="text-[11px] leading-snug" style={{ color: "rgba(35,41,29,0.6)" }}>
          Este es tu link personal: <span className="font-mono">{shareLink}</span>. Guárdalo en tu pantalla de inicio para verlo cuando quieras.
        </p>
      </div>

      {showGlamfit && (
        <GlamfitModal status={glamfitStatus} daysLeft={glamfitStatusInfo.daysLeft ?? null} onClose={() => setShowGlamfit(false)} />
      )}
      {showBeautyHouseModal && (
        <BeautyHouseModal status={beautyHouseStatus} onClose={() => setShowBeautyHouseModal(false)} />
      )}
    </div>
  );
}
